// Shared types for the board config headers. You normally do not edit this file;
// edit include/config_pilot.h, config_ops.h or config_command.h instead.
#pragma once
#include <stdint.h>

// HID axis slots, in the order they appear in the HID report.
// Linux evdev: ABS_X, ABS_Y, ABS_Z, ABS_RX, ABS_RY, ABS_RZ, ABS_THROTTLE, ABS_RUDDER
// SDL / Godot / Windows see them as axis index 0..7 in this order.
enum HidAxis : uint8_t { AX_X = 0, AX_Y, AX_Z, AX_RX, AX_RY, AX_RZ, AX_SLIDER, AX_DIAL, AX_COUNT };

// BIPOLAR: spring-centred (stick axes): min..center..max -> -32767..0..+32767
// UNIPOLAR: no centre (throttle, dimmer): min..max -> -32767..+32767
enum AxisMode : uint8_t { BIPOLAR = 0, UNIPOLAR = 1 };

struct AxisCfg {
  uint8_t pin;        // MUST be an ADC1 pin (GPIO1..GPIO10); ADC2 is unreliable with USB/Wi-Fi
  HidAxis slot;       // which HID axis it reports as
  AxisMode mode;
  bool invert;        // flip direction in firmware (game can also invert via input_map.json)
  uint8_t deadzonePct;// centre deadzone in % (BIPOLAR) or end deadzone (UNIPOLAR)
  const char *action; // game action name (documentation + input_map.json generator)
};

// Where a logical HID button gets its state from.
enum BtnSrc : uint8_t {
  SRC_GPIO = 0,  // switch from GPIO to GND, internal pull-up (active low)
  SRC_SR,        // bit N of the 74HC165 chain (bit 0 = input A of the chip nearest the ESP32)
  SRC_ENC_CW,    // EC11 encoder N turned clockwise: 1 pulse per detent
  SRC_ENC_CCW,   // EC11 encoder N turned counter-clockwise
  SRC_GPIO_HIGH, // GPIO that is active HIGH (e.g. optocoupler with external pull-down)
};

// Kind is only documentation for the game (exported to input_map.json):
//  momentary = push button, toggle = maintained switch (button held while ON),
//  rotary = one position of a rotary selector (exactly one held at a time),
//  pulse = encoder detent (short press per click)
enum BtnKind : uint8_t { K_MOMENTARY = 0, K_TOGGLE, K_ROTARY, K_PULSE };

struct ButtonCfg {
  BtnSrc src;
  uint8_t ref;        // GPIO number, shift-register bit, or encoder index
  uint8_t hid;        // HID button index, 0-based (0..63). joy.cpl only displays 0..31.
  BtnKind kind;
  const char *action; // game action name
};

struct EncoderCfg {
  uint8_t pinA, pinB;   // EC11 A/B to GPIO, C (middle pin) to GND. Push switch is a normal button.
  bool reverse;
};

// Macros used in the config headers. tools/gen_input_map.py parses these lines
// to produce shared/input_map.json, so keep ONE entry per line.
#define FF_AXIS(pin, slot, mode, inv, dz, action)  {pin, slot, mode, inv, dz, action}
#define FF_BTN(src, ref, hid, kind, action)        {src, ref, hid, kind, action}
